import { toast } from "react-hot-toast"
import { studentEndpoints } from "../api"
import { apiConnector } from "../apiconnector"
import { setPaymentLoading } from "../../slices/courseSlice"
import { resetCart } from "../../slices/cartSlice"
import { loadStripe } from "@stripe/stripe-js"

const { COURSE_PAYMENT_API, VERIFY_PAYMENT_API, SEND_PAYMENT_SUCCESS_EMAIL_API } = studentEndpoints

export async function buyCourse(token, courses, userDetails, navigate, dispatch) {
  const toastId = toast.loading("Processing payment...")
  dispatch(setPaymentLoading(true))
  try {
    // Load Stripe
    const stripe = await loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY)

    // Initiate the payment session
    const sessionResponse = await apiConnector(
      "POST",
      COURSE_PAYMENT_API,
      {
        products: courses,
        userId: userDetails._id,
      },
      {
        Authorization: `Bearer ${token}`,
      },
    )

    if (!sessionResponse.data.success) {
      throw new Error(sessionResponse.data.message)
    }

    // Redirect to Stripe checkout
    const result = await stripe.redirectToCheckout({
      sessionId: sessionResponse.data.id,
    })

    if (result.error) {
      throw new Error(result.error.message)
    }

    // If we get here, the redirect was successful
    toast.success("Redirecting to payment...")
  } catch (error) {
    console.log("PAYMENT API ERROR.....", error)
    toast.error(error.message || "Could not initiate payment")
  } finally {
    toast.dismiss(toastId)
    dispatch(setPaymentLoading(false))
  }
}

// This function will be called when redirected back from Stripe
export async function verifyPayment(sessionId, token, navigate, dispatch) {
  const toastId = toast.loading("Verifying payment...")
  dispatch(setPaymentLoading(true))
  try {
    const response = await apiConnector(
      "POST",
      VERIFY_PAYMENT_API,
      { sessionId },
      {
        Authorization: `Bearer ${token}`,
      },
    )

    if (!response.data.success) {
      throw new Error(response.data.message)
    }

    toast.success("Payment successful! You are now enrolled in the course.")
    dispatch(resetCart())
    navigate("/dashboard/enrolled-courses")
  } catch (error) {
    console.log("PAYMENT VERIFICATION ERROR.....", error)
    toast.error("Payment verification failed. Please contact support.")
  } finally {
    toast.dismiss(toastId)
    dispatch(setPaymentLoading(false))
  }
}

// Send payment success email (for direct API calls)
export async function sendPaymentSuccessEmail(orderId, paymentId, amount, token) {
  try {
    await apiConnector(
      "POST",
      SEND_PAYMENT_SUCCESS_EMAIL_API,
      {
        orderId,
        paymentId,
        amount,
      },
      {
        Authorization: `Bearer ${token}`,
      },
    )
  } catch (error) {
    console.log("PAYMENT SUCCESS EMAIL ERROR....", error)
  }
}
